import{V as e,et as t,gt as n,tt as r}from"./chunks/framework.qvtkvjpa.js";var i=JSON.parse(`{"title":"📠 更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":1783701175000}`),a={name:`guide/changelog.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="📠-更新日志" tabindex="-1">📠 更新日志 <a class="header-anchor" href="#📠-更新日志" aria-label="Permalink to “📠 更新日志”">​</a></h1><h2 id="_10-0-0" tabindex="-1">10.0.0 <a class="header-anchor" href="#_10-0-0" aria-label="Permalink to “10.0.0”">​</a></h2><p><code>2026-07-11</code></p><p>当前 10.x 版本相对 9.x 是一次主要版本升级，重点调整了数据接入、布局配置、坐标轴、指标、覆盖物、格式化和样式配置。</p><h3 id="新特性" tabindex="-1">新特性 <a class="header-anchor" href="#新特性" aria-label="Permalink to “新特性”">​</a></h3><ul><li>🆕 支持多 y 轴。同一窗口可以创建多个 y 轴，指标可以通过 <code>indicator.yAxisId</code> 绑定到指定 y 轴。</li><li>🆕 新增实例方法 <code>createYAxis(yAxis)</code>、<code>removeYAxis(filter)</code>、<code>getYAxes(filter)</code>、<code>overrideYAxis(options)</code> 和 <code>overrideXAxis(options)</code>。</li><li>🆕 支持自定义快捷键，新增 <code>hotkey</code> 初始化配置以及 <code>setHotkey</code>、<code>getHotkey</code>、<code>registerHotkey</code>、<code>getSupportedHotkeys</code> 等 API。</li><li>🆕 覆盖物支持连续绘制模式，内置覆盖物新增 <code>brush</code>。</li><li>🆕 支持千分符和小数 0 折叠自定义，新增 <code>thousandsSeparator</code>、<code>decimalFold</code> 配置以及对应实例 API。</li><li>🆕 支持设置缩放锚点，新增 <code>zoomAnchor</code> 配置以及 <code>setZoomAnchor(anchor)</code>、<code>getZoomAnchor()</code>。</li><li>🆕 支持通过 <code>setDataLoader(loader)</code> 统一接入历史数据、实时数据和向前加载数据。</li><li>🆕 支持通过 <code>setSymbol(symbol)</code>、<code>getSymbol()</code>、<code>setPeriod(period)</code>、<code>getPeriod()</code> 管理当前标的和周期。</li><li>🆕 支持在 x 轴显示未来时间。</li><li>🆕 支持移动端拖动 y 轴。</li><li>🆕 支持在同一窗口创建多个相同名称的指标。</li><li>🆕 重写坐标轴模块，自定义 y 轴支持自定义取值范围和分割信息。</li><li>🆕 指标图形新增 <code>text</code> 类型，指标 <code>figures</code> 可以直接绘制文本。</li><li>🆕 新增实例方法 <code>getIndicators(filter)</code> 和 <code>getOverlays(filter)</code> 用于按条件查询指标和覆盖物。</li><li>🆕 新增样式配置 <code>candle.priceMark.last.extendTexts</code>、<code>candle.tooltip.title</code>、<code>candle.tooltip.legend</code>、<code>indicator.tooltip.title</code>、<code>indicator.tooltip.legend</code>、<code>crosshair.horizontal.features</code>、<code>candle.bar.compareRule</code>、<code>indicator.ohlc.compareRule</code> 和 <code>candle.priceMark.last.compareRule</code>。</li><li>🆕 实例方法 <code>subscribeAction</code> 和 <code>unsubscribeAction</code> 的事件类型新增 <code>onIndicatorTooltipFeatureClick</code> 和 <code>onCrosshairFeatureClick</code>。</li></ul><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to “变更”">​</a></h3><ul><li>👉 图表方法 <code>init(ds, options)</code> 的 <code>options.layout</code> 调整为默认布局配置对象： <ul><li><code>layout.barSpaceLimit</code> 配置柱间距限制。</li><li><code>layout.pane</code> 配置默认窗口属性。</li><li><code>layout.yAxis</code> 配置默认 y 轴属性。</li></ul></li><li>👉 实例方法 <code>createIndicator(indicator, options?)</code> 调整为 <code>createIndicator(indicator, isStack?)</code>。指标所在窗口通过 <code>indicator.paneId</code> 指定，绑定的 y 轴通过 <code>indicator.yAxisId</code> 指定。</li><li>👉 <code>setPaneOptions(options)</code> 只负责窗口自身属性，坐标轴配置请使用 <code>overrideXAxis(options)</code>、<code>overrideYAxis(options)</code> 或多 y 轴相关 API。</li><li>👉 <code>convertToPixel(value, filter?)</code> 和 <code>convertFromPixel(coordinate, filter?)</code> 的 <code>filter</code> 新增 <code>yAxisId</code>。</li><li>👉 <code>options.customApi</code> 变更为 <code>options.formatter</code>，<code>setCustomApi</code> 变更为 <code>setFormatter</code>，<code>getCustomApi</code> 变更为 <code>getFormatter</code>。</li><li>👉 <code>formatDate(dateTimeFormat, timestamp, format, type)</code> 变更为 <code>formatDate({ dateTimeFormat, timestamp, template, type })</code>。</li><li>👉 <code>options.thousandsSeparator</code> 由简单配置变更为对象 <code>{ sign, format }</code>。</li><li>👉 <code>options.decimalFoldThreshold</code> 变更为 <code>options.decimalFold</code>。</li><li>👉 <code>getBarSpace()</code> 返回值由单值变更为对象。</li><li>👉 <code>createIndicator</code> 返回值变更为指标 id。</li><li>👉 自定义指标 <code>calc</code> 返回值由数组变更为以时间戳为 key 的对象。</li><li>👉 自定义指标 <code>createTooltipDataSource</code> 返回值中 <code>values</code> 变更为 <code>legends</code>，<code>icons</code> 变更为 <code>features</code>。</li><li>👉 样式配置 <code>candle.tooltip.icons</code> 变更为 <code>candle.tooltip.features</code>，<code>indicator.tooltip.icons</code> 变更为 <code>indicator.tooltip.features</code>。</li><li>👉 内置指标 <code>RSI</code> 计算逻辑调整。</li></ul><h3 id="移除" tabindex="-1">移除 <a class="header-anchor" href="#移除" aria-label="Permalink to “移除”">​</a></h3><ul><li>🗑 删除 <code>utils.drawArc</code>、<code>utils.drawCircle</code>、<code>utils.drawLine</code>、<code>utils.drawPolygon</code>、<code>utils.drawRect</code>、<code>utils.drawText</code> 和 <code>utils.drawRectText</code>，请使用 <code>getFigureClass(name)</code> 获取图形类。</li><li>🗑 删除实例方法 <code>setPriceVolumePrecision(pricePrecision, volumePrecision)</code>，请使用 <code>setSymbol(symbol)</code> 中的精度配置。</li><li>🗑 删除实例方法 <code>setLoadMoreData</code>、<code>applyNewData</code>、<code>applyMoreData</code>、<code>updateData</code>、<code>setLoadDataCallback</code> 和 <code>loadMore</code>，请使用 <code>setDataLoader(loader)</code>。</li><li>🗑 删除实例方法 <code>clearData()</code>，请使用 <code>resetData()</code> 重新加载数据。</li><li>🗑 删除实例方法 <code>getIndicatorByPaneId(paneId, name)</code>，请使用 <code>getIndicators(filter)</code>。</li><li>🗑 删除实例方法 <code>getOverlayById(id)</code>，请使用 <code>getOverlays(filter)</code>。</li><li>🗑 删除 <code>subscribeAction</code> 和 <code>unsubscribeAction</code> 中的 <code>onTooltipIconClick</code>，请使用 <code>onCandleTooltipFeatureClick</code> 和 <code>onIndicatorTooltipFeatureClick</code>。</li><li>🗑 删除样式配置 <code>yAxis.position</code>、<code>yAxis.type</code> 和 <code>yAxis.inside</code>，请使用 <code>init</code> 的 <code>layout.yAxis</code> 默认配置或实例 y 轴 API。</li><li>🗑 删除样式配置 <code>candle.tooltip.defaultValue</code>、<code>candle.tooltip.custom</code>、<code>candle.tooltip.text</code>、<code>indicator.tooltip.showName</code>、<code>indicator.tooltip.showParams</code>、<code>indicator.tooltip.defaultValue</code>、<code>indicator.tooltip.text</code> 和 <code>overlay.rectText</code>。</li><li>🗑 删除内置基础图形 <code>rectText</code>，请使用 <code>text</code>。</li></ul><h3 id="修复与优化" tabindex="-1">修复与优化 <a class="header-anchor" href="#修复与优化" aria-label="Permalink to “修复与优化”">​</a></h3><ul><li>🐞 修复覆盖物锁定状态下，事件落在覆盖物上时无法滚动图表的问题。</li><li>🐞 修复强制结束绘制的覆盖物无法通过 <code>createOverlay</code> 恢复的问题。</li><li>🐞 修复覆盖物弱磁模式下绘制响应问题。</li><li>🐞 修复向后加载数据可能无限触发数据请求回调的问题。</li><li>🐞 修复 <code>resize</code> 可能不生效的问题。</li><li>🐞 修复实例 API <code>setZoomAnchor</code> 参数类型错误。</li><li>💄 图表支持容器尺寸自动监听和自动 <code>resize()</code>。</li><li>💄 优化覆盖物模版中 <code>figure</code> 的事件忽略类型，使事件名和 <code>overlay</code> 中的事件名称一致。</li><li>💄 优化指标计算任务执行。</li><li>💄 优化移动端滚动事件触发。</li><li>💄 优化构建流程，构建工具由 Rollup 调整为 Vite，并新增 <code>type-check</code> 校验。</li></ul><h2 id="_9-x" tabindex="-1">9.x <a class="header-anchor" href="#_9-x" aria-label="Permalink to “9.x”">​</a></h2><p>去 <a href="https://v9.klinecharts.com" target="_blank" rel="noreferrer">https://v9.klinecharts.com</a> 上查看。</p><h2 id="_8-x" tabindex="-1">8.x <a class="header-anchor" href="#_8-x" aria-label="Permalink to “8.x”">​</a></h2><p>去 <a href="https://v8.klinecharts.com" target="_blank" rel="noreferrer">https://v8.klinecharts.com</a> 上查看。</p><h2 id="_7-x" tabindex="-1">7.x <a class="header-anchor" href="#_7-x" aria-label="Permalink to “7.x”">​</a></h2><p>去 <a href="https://github.com/liihuu/KLineChart/blob/v7.5.0/docs/zh-CN/changelog.md" target="_blank" rel="noreferrer">Github</a> 上查看 7.x 的 Change Log。</p><h2 id="_6-x" tabindex="-1">6.x <a class="header-anchor" href="#_6-x" aria-label="Permalink to “6.x”">​</a></h2><p>去 <a href="https://github.com/liihuu/KLineChart/blob/v6.1.0/docs/zh-CN/CHANGELOG.md" target="_blank" rel="noreferrer">Github</a> 上查看 6.x 的 Change Log。</p><h2 id="_5-x" tabindex="-1">5.x <a class="header-anchor" href="#_5-x" aria-label="Permalink to “5.x”">​</a></h2><p>去 <a href="https://github.com/liihuu/KLineChart/releases/tag/v5.0.0" target="_blank" rel="noreferrer">Github</a> 上查看 5.x 的版本记录。</p><h2 id="_4-x" tabindex="-1">4.x <a class="header-anchor" href="#_4-x" aria-label="Permalink to “4.x”">​</a></h2><p>去 <a href="https://github.com/liihuu/KLineChart/releases/tag/v4.0.0" target="_blank" rel="noreferrer">Github</a> 上查看 4.x 的版本记录。</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};